type commandUsageResult struct {
	// ExecutionOutcome, when set, is the execution the command reported
	// (e.g. waiting) and replaces the one derived from its exit code.
	ExecutionOutcome   string
	SemanticOutcome    string
	Findings           []usagepkg.Finding
	FindingCount       int
	FindingsBySeverity map[string]int
	FindingSetComplete bool
	Signals            []string
}

type usageFinding struct {
	ID       string
	Severity string
}

type usageOutput struct {
	io.Writer
	result *commandUsageResult
	// noRecord belongs to this invocation; write-free commands set it after
	// their own option parser selects preview, rather than setting global flags.
	noRecord bool
}

// UnwrapWriter exposes the stream underneath, so capability detection sees the
// terminal rather than this wrapper (spec pose-cli-output-rendering-system R1).
func (w *usageOutput) UnwrapWriter() io.Writer { return w.Writer }

func (w *usageOutput) note(result commandUsageResult) {
	copy := result
	w.result = &copy
}

func suppressCommandUsage(stdout io.Writer) {
	if output, ok := stdout.(*usageOutput); ok {
		output.noRecord = true
	}
}

func noteCommandUsage(stdout io.Writer, result commandUsageResult) {
	if output, ok := stdout.(*usageOutput); ok {
		output.note(result)
	}
}

func noteUsageSignals(stdout io.Writer, signals ...string) {
	output, ok := stdout.(*usageOutput)
	if !ok {
		return
	}
	if output.result == nil {
		output.result = &commandUsageResult{SemanticOutcome: "unknown"}
	}
	output.result.Signals = append(output.result.Signals, signals...)
}

func mainWithUsage(args []string, stdout, stderr io.Writer) int {
	started := time.Now()
	root, rootErr := projectRoot()
	original := append([]string(nil), args...)
	tool := "help"
	if len(original) > 0 {
		tool = commandUsageTool(original)
	}
	wrapped := &usageOutput{Writer: stdout}
	code := mainCommand(args, wrapped, stderr)
	if wrapped.noRecord || rootErr != nil || !shouldRecordCLIUsage(tool, code) {
		return code
	}
	result := defaultCommandUsage(tool, code)
	if wrapped.result != nil {
		result = *wrapped.result
	}
	execution := "completed"
	if code == 2 {
		execution = "invalid"
	} else if code != 0 && !isGateCommand(tool) {
		execution = "failed"
	}
	if result.ExecutionOutcome != "" && code != 2 {
		execution = result.ExecutionOutcome
	}
	scopeArgs := original[1:]
	observation := usagepkg.Observation{
		At: time.Now().UTC(), Tool: tool, Surface: "cli",
		DurationMS:       float64(time.Since(started).Microseconds()) / 1000,
		ExecutionOutcome: execution, SemanticOutcome: result.SemanticOutcome,
		Findings: result.Findings, FindingCount: result.FindingCount,
		FindingsBySeverity: result.FindingsBySeverity,
		FindingSetComplete: result.FindingSetComplete,
		Scope:              strings.Join(scopeArgs, "\x00"), Version: Version,
	}
	_ = usagepkg.Record(root, observation)
	for _, signal := range compactUsageSignals(result.Signals) {
		observation.Tool = "review.signal." + signal
		// A derived signal has no interval of its own; recording 0 ms would
		// average a time nobody measured (spec pose-cli-mcp-operation-results R8).
		observation.DurationMS = 0
		observation.DurationUnknown = true
		observation.Findings = nil
		observation.FindingCount = 0
		observation.FindingsBySeverity = nil
		observation.FindingSetComplete = false
		_ = usagepkg.Record(root, observation)
	}
	return code
}

func commandUsageTool(args []string) string {
	if len(args) < 2 || args[0] != "review" {
		return args[0]
	}
	switch args[1] {
	case "bundle":
		for _, arg := range args[2:] {
			if arg == "--seal" {
				return "review.bundle.seal"
