func (s Store) ListRoadmaps() ([]Roadmap, error) {
	entries, err := s.fsys().ReadDir(s.roadmapsDir())
	if err != nil {
		if os.IsNotExist(err) {
			return []Roadmap{}, nil
		}
		return nil, fmt.Errorf("pose: reading roadmaps dir: %w", err)
	}
	roadmaps := []Roadmap{}
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".md") || strings.EqualFold(e.Name(), "README.md") {
			continue
		}
		slug := strings.TrimSuffix(e.Name(), ".md")
		rm, err := parseRoadmapFile(s.fsys(), filepath.Join(s.roadmapsDir(), e.Name()), slug, false)
		if err != nil {
			continue // um artefato quebrado não derruba a listagem
		}
		roadmaps = append(roadmaps, *rm)
	}
	sort.Slice(roadmaps, func(i, j int) bool { return roadmaps[i].Slug < roadmaps[j].Slug })
	return roadmaps, nil
}

func parseRoadmapFile(files Files, path, slug string, includeBody bool) (*Roadmap, error) {
	raw, err := files.ReadFile(path)
	if err != nil {
		return nil, err
	}
	fm, body := SplitFrontmatter(string(raw))
	rm := &Roadmap{Slug: slug, Path: path, Milestones: []Milestone{}}
	for key, value := range fm {
		switch key {
		case "slug":
			if value != "" {
				rm.Slug = value
			}
		case "status":
			rm.Status = value
		case "created_at":
			rm.CreatedAt = value
		case "depends_on":
			rm.DependsOn = parseInlineList(value)
		case "consumes":
			rm.Consumes = parseInlineList(value)
		case "unreviewed_milestones":
			rm.UnreviewedMilestones = cleanValue(value)
		case "adrs":
			rm.ADRs = strings.TrimSpace(value)
		}
	}
	var current *Milestone
	inGate := false
	for _, line := range strings.Split(body, "\n") {
		stripped := strings.TrimSpace(line)
		if inGate {
			if stripped == "" || strings.HasPrefix(stripped, "#") || strings.HasPrefix(stripped, "- ") {
				inGate = false
			} else {
				current.ExitGate += " " + stripped
				continue
			}
		}
		if text, ok := strings.CutPrefix(stripped, "**Exit gate:**"); ok && current != nil {
			current.ExitGate, inGate = strings.TrimSpace(text), true
			continue
		}
		if m := milestoneHeadingRE.FindStringSubmatch(stripped); m != nil {
			rm.Milestones = append(rm.Milestones, Milestone{ID: m[1]})
			current = &rm.Milestones[len(rm.Milestones)-1]
			continue

func cleanValue(v string) string {
	v = strings.TrimSpace(v)
	if strings.HasPrefix(v, "#") {
		return "" // value is only a template comment
	}
	if i := strings.Index(v, " #"); i >= 0 {
		v = v[:i] // strip trailing template comment
	}
	return strings.TrimSpace(v)
}

// parseInlineList parses a flat inline list value ("a, b" or "[a, b]") into
// its trimmed, non-empty items. Used for both `depends_on` (refs keep their
// typed prefixes, e.g. milestone:/roadmap:, verbatim — resolution semantics
// live in SpecReadiness, not in parsing) and `components` (free-form tags).
func parseInlineList(value string) []string {

		case "language":
			component.Language = ""
		case "owner":
			component.Owner = ""
		case "domain":
			component.Domain = ""
		case "criticality":
			component.Criticality = ""
		case "validationprofile", "validation_profile":
			component.ValidationProfile = ""
		}
	}
}

func (s Store) reviewScopeSpecs(scope ScopeRef) ([]Spec, error) {
	slugs := []string{}
	switch scope.Kind {
	case "spec":
		slugs = append(slugs, scope.Slug)
	case "milestone":
		rm, err := s.GetRoadmap(scope.Roadmap)
		if err != nil {
			return nil, err
		}
		found := false
		for _, milestone := range rm.Milestones {
			if milestone.ID == scope.Milestone {
				slugs, found = append(slugs, milestone.Specs...), true
			}
		}
		if !found {
			return nil, fmt.Errorf("pose: milestone %s/%s not found", scope.Roadmap, scope.Milestone)
		}
	case "roadmap":
		rm, err := s.GetRoadmap(scope.Slug)
		if err != nil {
			return nil, err
		}
		for _, milestone := range rm.Milestones {
			slugs = append(slugs, milestone.Specs...)
		}
	}
	specs := []Spec{}
	for _, raw := range uniqueSorted(slugs) {
		// Another project's member contributes no local components; its
		// review lives in its own project and reaches this scope through the
		// federated manifest.
		slug, external := s.milestoneMember(raw)
		if external {
			continue
		}
		sp, err := s.GetSpec(slug)
		if err != nil {
			return nil, err
		}
		specs = append(specs, *sp)
	}
	return specs, nil
}

