func (s Store) SpecReadiness(slug string) (*Readiness, error) {
	resolver, project, err := EnvironmentArtifactResolverIn(s.fsys(), s.Root, "")
	if err != nil {
		return nil, err
	}
	return s.SpecReadinessWithResolver(slug, project, resolver)
}

// SpecReadinessWithResolver lets transports enforce their caller's project policy.
func (s Store) SpecReadinessWithResolver(slug, project string, resolver ArtifactResolver) (*Readiness, error) {
	if view, _ := governanceReadViewFromFiles(s.fsys()); view != nil && view.operation != nil {
		// Producer-created resolvers retain their caller's roots and authority,
		// while sharing the captured operation's dependency traversal budget.
		resolver.governanceDepthLimit = view.operation.resolver.governanceDepthLimit
	}
	sp, err := s.GetSpec(slug)
	if err != nil {
		return nil, err
	}
	r := &Readiness{Slug: sp.Slug, Status: sp.Status, WaitingOn: []WaitingRef{}}

	if terminalStatuses[sp.Status] {
		r.Terminal = true
		r.Reason = fmt.Sprintf("spec is in terminal status %q", sp.Status)
		return r, nil
	}
	// A blocked spec stays not ready, as it always was, but it is no longer a
	// bare bit: its declared prerequisites are still resolved so the waiting
	// set explains the block when it can, and an unexplained block says so.
	blocked := sp.Status == "blocked"

	// Definition of Ready (pose-definition-of-ready): specs criadas a partir do
	// cutoff de adoção precisam de acceptance criteria com IDs estáveis antes de
	// serem elegíveis. Specs anteriores são legadas (isentas) — o gate de
	// transição do pose check cobre o funil novo.
	if s.dorApplies(sp.CreatedAt) && !hasAcceptanceCriteriaIDs(sp.Body) {
		r.WaitingOn = append(r.WaitingOn, WaitingRef{
			Ref:    "dor:acceptance-criteria",
			Reason: "Definition of Ready: no acceptance criteria with stable IDs (- R<N>: ...) in Requirements",
			Code:   "dor-acceptance-criteria-missing",
		})
	}

	for _, raw := range sp.DependsOn {
		ref, parseErr := ParseArtifactRef(raw)
		reason, state, graph, notDone := "", "", "", false
		if parseErr != nil {
			reason, state = "invalid-artifact-reference", "invalid-artifact-reference"
		} else {
			resolved := resolver.Resolve(project, raw)
			if !resolved.Resolved {
				reason, state = resolved.State, resolved.State
			} else if graphReason := resolver.ValidateGraph(project, raw); graphReason != "" {
				reason, graph = graphReason, graphReason
			} else if resolved.Status != "done" {
				notDone = true
				reason = fmt.Sprintf("%s status is %q (needs done)", ref.Kind, resolved.Status)
				if ref.Kind == "milestone" && ref.Project == "" {
					reason = s.milestoneWaitingReason(ref.Slug + "/" + ref.Milestone)
				}
			} else if closed, why := s.AggregateDependencyClosed(resolver, project, resolved); !closed {
				notDone, reason = true, why
			}
		}
		if reason != "" {
			r.WaitingOn = append(r.WaitingOn, WaitingRef{Ref: raw, Reason: reason, Code: dependencyWaitingCode(state, graph, notDone), Detail: firstNonempty(state, graph)})
		}
	}

	if blocked {
		dependencies := 0
		for _, waiting := range r.WaitingOn {
			if !strings.HasPrefix(waiting.Ref, "dor:") {
				dependencies++
			}
		}
		if dependencies > 0 {
			r.Cause = ReadinessCauseDependency
			r.Reason = fmt.Sprintf("spec is blocked (an operational condition, not a terminal status) and waits on %d unsatisfied dependency(ies)", dependencies)
		} else {
			r.Cause = ReadinessCauseUnknown
			r.Reason = "spec is blocked (an operational condition, not a terminal status) and no recorded cause explains it"
		}
		return r, nil
	}
	r.Ready = len(r.WaitingOn) == 0
	if !r.Ready && r.Reason == "" {
		r.Reason = fmt.Sprintf("%d unsatisfied dependency(ies)", len(r.WaitingOn))
	}
	return r, nil
}

